import os, re, json

repo_root = '.'
findings = {}

search_keys = {
    'gile': [r'gile', r'goodness', r'intuition', r'love', r'elegance'],
    'hem_gile': [r'hem:gile', r'gile:hem', r'hem/gile', r'ratio'],
    'truth_labels': [r'indeterminate', r'meta-indeterminate', r'tralse', r'5-valued', r'five-valued', r'belnap', r'priest'],
    'label_metrics': [r'fleiss', r'kappa', r'mutual information', r'entropy', r'exhaustion', r'completeness', r'coverage', r'effective rank', r'confusion matrix'],
    'truth_axes': [r'truth axes', r'real', r'imaginary', r'authority', r'pragmatic'],
    'pd': r'\b(pd|potentiality deficit|-3 to \+2|4/3|euler)\b',
    'crystal': r'\bcrystal\b',
    'graph': r'\bgraph\b',
    'myrion': r'\bmyrion\b'
}

for root, dirs, files in os.walk(repo_root):
    if '.git' in dirs:
        dirs.remove('.git')
    for file in files:
        if file.endswith(('.md', '.py', '.json', '.txt')):
            rel_path = os.path.normpath(os.path.relpath(os.path.join(root, file), repo_root)).replace('\\', '/')
            try:
                with open(rel_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
                    for k, pat in search_keys.items():
                        if isinstance(pat, list):
                            matches = [p for p in pat if re.search(p, content, re.I)]
                            if len(matches) >= 2:
                                if k not in findings: findings[k] = set()
                                findings[k].add(rel_path)
                        else:
                            if re.search(pat, content, re.I):
                                if k not in findings: findings[k] = set()
                                findings[k].add(rel_path)
            except Exception as e:
                pass

for k, files in findings.items():
    print(f'=== {k.upper()} (found in {len(files)} files) ===')
    for f in sorted(list(files))[:10]:
        print('  ', f)
